bject","properties":{"kind":{"type":"string","const":"calendar_change"},"calendarId":{"type":"string","minLength":1,"maxLength":512,"pattern":"^[^\\s\\u0000-\\u001f\\u007f]+$"},"eventId":{"type":"string","minLength":1,"maxLength":512,"pattern":"^[^\\s\\u0000-\\u001f\\u007f]+$"},"expectedEtag":{"type":"string","minLength":1,"maxLength":512,"pattern":"^[^\\s\\u0000-\\u001f\\u007f]+$"}},"required":["kind","calendarId","eventId","expectedEtag"],"additionalProperties":false},"purpose":{"type":"string","minLength":1,"maxLength":1000},"preparedAt":{"type":"string","format":"date-time","pattern":"^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))T(?:(?:[01]\\d|2[0-3]):[0-5]\\d:[0-5]\\d(?:\\.\\d+)?(?:Z|([+-](?:[01]\\d|2[0-3]):[0-5]\\d)))$"},"confirmBy":{"type":"string","format":"date-time","pattern":"^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))T(?:(?:[01]\\d|2[0-3]):[0-5]\\d:[0-5]\\d(?:\\.\\d+)?(?:Z|([+-](?:[01]\\d|2[0-3]):[0-5]\\d)))$"},"expiresAt":{"type":"string","format":"date-time","pattern":"^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))T(?:(?:[01]\\d|2[0-3]):[0-5]\\d:[0-5]\\d(?:\\.\\d+)?(?:Z|([+-](?:[01]\\d|2[0-3]):[0-5]\\d)))$"},"permission":{"type":"string","const":"read_single_calendar_event"},"outboundEffects":{"type":"string","const":"forbidden"},"continuesAfterSignOut":{"type":"boolean","const":true}},"required":["id","token","rootTitle","siteName","accountEmail","target","purpose","preparedAt","confirmBy","expiresAt","permission","outboundEffects","continuesAfterSignOut"],"additionalProperties":false},"event":{"$schema":"http://json-schema.org/draft-07/schema#","type":"object","properties":{"kind":{"type":"string","const":"calendar#event"},"id":{"type":"string","minLength":1,"maxLength":512,"pattern":"^[^\\s\\u0000-\\u001f\\u007f]+$"},"etag":{"type":"string","minLength":1,"maxLength":512,"pattern":"^[^\\s\\u0000-\\u001f\\u007f]+$"},"status":{"type":"string","enum":["confirmed","tentative","cancelled"]},"updated":{"type":"string","format":"date-time","pattern":"^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))T(?:(?:[01]\\d|2[0-3]):[0-5]\\d:[0-5]\\d(?:\\.\\d+)?(?:Z|([+-](?:[01]\\d|2[0-3]):[0-5]\\d)))$"},"summary":{"type":"string","maxLength":4096},"description":{"type":"string","maxLength":131072},"location":{"type":"string","maxLength":8192},"start":{"type":"object","properties":{"date":{"type":"string","maxLength":16},"dateTime":{"type":"string","format":"date-time","pattern":"^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))T(?:(?:[01]\\d|2[0-3]):[0-5]\\d:[0-5]\\d(?:\\.\\d+)?(?:Z|([+-](?:[01]\\d|2[0-3]):[0-5]\\d)))$"},"timeZone":{"type":"string","maxLength":128}},"additionalProperties":false},"end":{"type":"object","properties":{"date":{"type":"string","maxLength":16},"dateTime":{"type":"string","format":"date-time","pattern":"^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))T(?:(?:[01]\\d|2[0-3]):[0-5]\\d:[0-5]\\d(?:\\.\\d+)?(?:Z|([+-](?:[01]\\d|2[0-3]):[0-5]\\d)))$"},"timeZone":{"type":"string","maxLength":128}},"additionalProperties":false}},"required":["kind","id","etag","status","updated"],"additionalProperties":false}}$schema$::jsonb->k $$;

-- Source: .local/native-google-access/draft.sql
-- Unnumbered, unmounted draft. Managed owner only. No deployment role grants here.
CREATE TABLE pactwoven.native_google_access_bindings(login name,role_oid oid NOT NULL,environment text,lane text CHECK(lane IN('observer','api','review','content')),PRIMARY KEY(login,environment,lane));
CREATE TABLE pactwoven.native_google_access_settings(environment text PRIMARY KEY,issuer text NOT NULL,client_id text NOT NULL,redirect_uri text NOT NULL,expected_email text NOT NULL,enabled boolean NOT NULL DEFAULT false);
CREATE TABLE pactwoven.native_google_access_sessions(environment text,id text,producer name NOT NULL,producer_oid oid NOT NULL,evidence jsonb NOT NULL,PRIMARY KEY(environment,id));
CREATE TABLE pactwoven.native_google_access_reviews(environment text,organization_id text,id text,actor_id text NOT NULL,request_key text NOT NULL,producer name NOT NULL,producer_oid oid NOT NULL,input jsonb NOT NULL,request jsonb NOT NULL,binding jsonb NOT NULL,review jsonb NOT NULL,session_id text NOT NULL,authenticated_at timestamptz NOT NULL,approval jsonb,approval_session jsonb,PRIMARY KEY(environment,organization_id,id),UNIQUE(environment,organization_id,actor_id,request_key));
CREATE TABLE pactwoven.native_google_access_contents(environment text,id text,connection_id text NOT NULL,target jsonb NOT NULL,event_digest text NOT NULL,reference jsonb NOT NULL,body jsonb NOT NULL,PRIMARY KEY(environment,id));
CREATE FUNCTION pactwoven.native_google_access_validate(v jsonb,k text)RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN PERFORM pactwoven.native_google_require(octet_length(v::text)<=262144 AND pactwoven.native_delegation_matches(v,pactwoven.native_google_access_schema(k)));END $$;
CREATE FUNCTION pactwoven.native_google_access_producer(env text,login_name name,login_oid oid,p_lane text)RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN PERFORM 1 FROM pactwoven.native_google_access_bindings b JOIN pg_roles r ON r.oid=b.role_oid AND r.rolname=b.login WHERE b.environment=env AND b.login=login_name AND b.role_oid=login_oid AND b.lane=p_lane AND NOT(r.rolsuper OR r.rolcreatedb OR r.rolcreaterole OR r.rolbypassrls OR r.rolreplication)FOR SHARE OF b;PERFORM pactwoven.native_google_require(FOUND,'NG001');END $$;
CREATE FUNCTION pactwoven.native_google_access_lane(env text,p_lane text)RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN PERFORM pactwoven.financial_require_read_committed();PERFORM set_config('lock_timeout','2000ms',true);PERFORM pactwoven.native_google_access_producer(env,SESSION_USER,(SELECT oid FROM pg_roles WHERE rolname=SESSION_USER),p_lane);END $$;
CREATE FUNCTION pactwoven.native_google_access_config(env text)RETURNS pactwoven.native_google_access_settings LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE c pactwoven.native_google_access_settings;BEGIN SELECT * INTO c FROM pactwoven.native_google_access_settings WHERE environment=env FOR SHARE;PERFORM pactwoven.native_google_require(FOUND AND c.enabled AND c.issuer~'^https://[a-z0-9.-]+$' AND c.redirect_uri~'^https://[a-z0-9.-]+/app/settings/connections/google/callback$' AND c.client_id~'^[A-Za-z0-9_-]+\.apps\.googleusercontent\.com$' AND c.expected_email='richverseecotech@gmail.com','NG010');RETURN c;END $$;
-- Fence creation and reservation before a connection URL or code exchange is possible.
CREATE FUNCTION pactwoven.native_google_access_attempt_config()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c pactwoven.native_google_access_settings;BEGIN
IF NEW.status IN('pending','reserved') THEN c:=pactwoven.native_google_access_config(NEW.environment);PERFORM pactwoven.native_google_require(NEW.body->>'clientId'=c.client_id AND NEW.body->>'redirectUri'=c.redirect_uri AND NEW.body->>'expectedEmail'=c.expected_email,'NG010');END IF;
RETURN NEW;END $$;
CREATE OR REPLACE TRIGGER native_google_access_attempt_config BEFORE INSERT OR UPDATE ON pactwoven.native_google_attempts FOR EACH ROW EXECUTE FUNCTION pactwoven.native_google_access_attempt_config();
CREATE FUNCTION pactwoven.native_google_access_human(env text,e jsonb,site text DEFAULT NULL)RETURNS timestamptz LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE s jsonb:=e->'session';a jsonb:=s->'actor';o pactwoven.organizations;m pactwoven.memberships;f pactwoven.financial_site_fences;c pactwoven.native_google_access_settings;BEGIN
c:=pactwoven.native_google_access_config(env);PERFORM pactwoven.native_google_session_fresh(s);
SELECT * INTO o FROM pactwoven.organizations WHERE(environment,id)=(env,a->>'organizationId')FOR SHARE;
SELECT * INTO m FROM pactwoven.memberships WHERE(environment,organization_id,actor_id)=(env,o.id,a->>'actorId')FOR SHARE;
LOCK TABLE pactwoven.session_revocations IN SHARE MODE;
PERFORM pactwoven.native_google_require(a->>'environment'=env AND o.status='active' AND m.status='active' AND(m.expires_at IS NULL OR m.expires_at>clock_timestamp()) AND m.roles&&ARRAY['owner','operations'] AND o.external_organization_id=e->>'externalOrganizationId' AND m.external_subject=s->>'subject' AND m.external_membership_id=e->>'externalMembershipId' AND(m.grant_basis<>'clerk_admin_bootstrap' OR e->>'externalRole'='org:admin') AND e->>'issuer'=c.issuer AND NOT EXISTS(SELECT 1 FROM pactwoven.session_revocations WHERE(environment,session_id)=(env,a->>'sessionId')),'NG001');
IF site IS NOT NULL THEN
 PERFORM 1 FROM pactwoven.sites WHERE(environment,organization_id,id)=(env,o.id,site)FOR SHARE;PERFORM pactwoven.native_google_require(FOUND,'NG001');
 SELECT * INTO f FROM pactwoven.financial_site_fences WHERE(environment,organization_id,site_id)=(env,o.id,site)FOR SHARE;
 PERFORM 1 FROM pactwoven.member_action_sites WHERE(environment,organization_id,actor_id,site_id)=(env,o.id,m.actor_id,site)FOR SHARE;PERFORM pactwoven.native_google_require(FOUND AND f.active,'NG001');
 IF NOT 'owner'=ANY(m.roles) THEN PERFORM 1 FROM pactwoven.site_memberships WHERE(environment,organization_id,actor_id,site_id)=(env,o.id,m.actor_id,site)FOR SHARE;PERFORM pactwoven.native_google_require(FOUND,'NG001');END IF;
END IF;
PERFORM pactwoven.native_google_session_fresh(s);PERFORM pactwoven.native_google_require(m.expires_at IS NULL OR m.expires_at>clock_timestamp(),'NG008');RETURN m.expires_at;END $$;
CREATE FUNCTION pactwoven.native_google_access_observe(env text,e jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE s jsonb:=e->'session';old jsonb;expiry timestamptz;BEGIN
PERFORM pactwoven.native_google_access_lane(env,'observer');PERFORM pactwoven.native_google_access_validate(e,'identity');
PERFORM pactwoven.native_google_require((e->>'tokenIssuedAt')::timestamptz<=(s->>'verifiedAt')::timestamptz,'NG001');expiry:=pactwoven.native_google_access_human(env,e);
INSERT INTO pactwoven.native_google_access_sessions VALUES(env,s->>'proofId',SESSION_USER,(SELECT oid FROM pg_roles WHERE rolname=SESSION_USER),e)ON CONFLICT DO NOTHING;
SELECT evidence INTO old FROM pactwoven.native_google_access_sessions WHERE(environment,id)=(env,s->>'proofId');PERFORM pactwoven.native_google_require(old=e,'NG003');
PERFORM pactwoven.native_google_session_fresh(s);PERFORM pactwoven.native_google_require(expiry IS NULL OR expiry>clock_timestamp(),'NG008');RETURN s;END $$;
CREATE OR REPLACE FUNCTION pactwoven.native_google_bridge_session(env text,input jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE p pactwoven.native_google_access_sessions;BEGIN SELECT * INTO p FROM pactwoven.native_google_access_sessions WHERE(environment,id)=(env,input->>'proofId')FOR SHARE;
PERFORM pactwoven.native_google_require(FOUND AND p.evidence->'session'=input,'NG001');PERFORM pactwoven.native_google_access_producer(env,p.producer,p.producer_oid,'observer');PERFORM pactwoven.native_google_access_human(env,p.evidence);RETURN input;END $$;
CREATE FUNCTION pactwoven.native_google_access_session(env text,s jsonb,site text DEFAULT NULL)RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE e jsonb;BEGIN PERFORM pactwoven.native_google_validate(s,'session');PERFORM pactwoven.native_google_bridge_session(env,s);SELECT evidence INTO e FROM pactwoven.native_google_access_sessions WHERE(environment,id)=(env,s->>'proofId');PERFORM pactwoven.native_google_access_human(env,e,site);END $$;
CREATE FUNCTION pactwoven.native_google_access_root(env text,org text,actor_id text,root_id text,site text,worker boolean)RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE r pactwoven.native_delegation_root_runs;t pactwoven.native_delegation_tasks;g pactwoven.native_delegation_grants;p pactwoven.native_delegation_proofs;binding jsonb;expiry timestamptz;stamp timestamptz;cfg pactwoven.native_google_access_settings;BEGIN
cfg:=pactwoven.native_google_access_config(env);
SELECT * INTO r FROM pactwoven.native_delegation_root_runs WHERE(environment,organization_id,root_task_id)=(env,org,root_id);PERFORM pactwoven.native_google_require(FOUND,'NG001');g:=pactwoven.native_delegation_grant_locked(env,org,r.grant_id);
SELECT * INTO r FROM pactwoven.native_delegation_root_runs WHERE(environment,organization_id,root_task_id)=(env,org,root_id)FOR SHARE;
SELECT * INTO t FROM pactwoven.native_delegation_tasks WHERE(environment,organization_id,id)=(env,org,root_id)FOR SHARE;
PERFORM pactwoven.native_google_require(g.body#>>'{scope,issuer,providerIssuer}'=cfg.issuer AND r.actor_id=actor_id AND r.site_id=site AND g.actor_id=actor_id AND g.root_task_id=root_id AND t.depth=0 AND t.grant_id=g.id AND t.site_id=site AND t.authority=pactwoven.native_delegation_reference(g) AND t.state IN('ready','running') AND r.phase IN('ready','running','yielded','waiting_children') AND NOT r.manual_paused,'NG001');
binding:=pactwoven.native_delegation_provider_binding(g,t);expiry:=LEAST((g.body->>'expiresAt')::timestamptz,t.deadline_at,(binding->>'memberExpiry')::timestamptz);
IF worker THEN SELECT * INTO p FROM pactwoven.native_delegation_proofs WHERE(environment,organization_id,task_id)=(env,org,root_id)FOR SHARE;PERFORM pactwoven.native_google_require(FOUND AND p.verdict='allowed' AND p.binding=binding AND p.valid_until>clock_timestamp(),'NG001');expiry:=LEAST(expiry,p.valid_until);END IF;
stamp:=clock_timestamp();PERFORM pactwoven.native_google_require(expiry>stamp,'NG008');
RETURN jsonb_build_object('root',jsonb_build_object('scope',jsonb_build_object('environment',env,'organizationId',org,'siteId',site),'rootTaskId',root_id,'actorId',actor_id,'authority',t.authority,'generation',t.generation,'controlVersion',r.control_version,'state',CASE WHEN r.phase='ready' THEN 'ready' ELSE 'running' END,'expiresAt',pactwoven.mandate_instant(expiry)),
 'authority',jsonb_build_object('scope',jsonb_build_object('environment',env,'organizationId',org,'siteId',site),'actorId',actor_id,'membershipVersion',g.body#>'{scope,issuer,membershipVersion}','organizationEpoch',g.body#>'{scope,organizationEpoch}','state','current','observedAt',pactwoven.mandate_instant(stamp),'validUntil',pactwoven.mandate_instant(LEAST(expiry,stamp+interval '15 seconds'))),'rootTitle',r.title);EXCEPTION WHEN SQLSTATE 'ND001' THEN RAISE EXCEPTION USING ERRCODE='NG001',MESSAGE='Current root authority required';END $$;
CREATE FUNCTION pactwoven.native_google_access_connection(env text,p_id text)RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE c jsonb;cfg pactwoven.native_google_access_settings;BEGIN cfg:=pactwoven.native_google_access_config(env);SELECT body INTO c FROM pactwoven.native_google_connections WHERE(environment,id)=(env,p_id)FOR UPDATE;
PERFORM pactwoven.native_google_require(c->>'status' IN('connected','refreshing') AND c->>'clientId'=cfg.client_id AND c->>'accountEmail'=cfg.expected_email,'NG001');RETURN c;END $$;
CREATE FUNCTION pactwoven.native_google_access_prepare(env text,s jsonb,key text,q jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
#variable_conflict use_variable
DECLARE c jsonb;ctx jsonb;req jsonb;bind jsonb;review jsonb;old pactwoven.native_google_access_reviews;stamp timestamptz;rid text:=gen_random_uuid()::text;site_name text;BEGIN
PERFORM pactwoven.native_google_access_lane(env,'api');PERFORM pactwoven.native_google_access_validate(q,'prepare');PERFORM pactwoven.native_google_require(key~'^[A-Za-z0-9_-]{16,128}$');c:=pactwoven.native_google_access_connection(env,q->>'connectionId');PERFORM pactwoven.native_google_access_session(env,s,q->>'siteId');
PERFORM pactwoven.native_google_require(c#>>'{binding,actorId}'=s#>>'{actor,actorId}' AND c#>>'{binding,organizationId}'=s#>>'{actor,organizationId}','NG001');
PERFORM pg_advisory_xact_lock(hashtextextended(env||':'||(s#>>'{actor,organizationId}')||':'||(s#>>'{actor,actorId}')||':'||key,0));
ctx:=pactwoven.native_google_access_root(env,s#>>'{actor,organizationId}',s#>>'{actor,actorId}',q->>'rootTaskId',q->>'siteId',false);stamp:=clock_timestamp();
PERFORM pactwoven.native_google_require((q->>'expiresAt')::timestamptz>stamp AND(q->>'expiresAt')::timestamptz<=LEAST(stamp+interval '24 hours',(ctx#>>'{root,expiresAt}')::timestamptz),'NG003');
SELECT * INTO old FROM pactwoven.native_google_access_reviews WHERE(environment,organization_id,actor_id,request_key)=(env,s#>>'{actor,organizationId}',s#>>'{actor,actorId}',key);
IF FOUND THEN PERFORM pactwoven.native_google_require(old.input=q AND old.session_id=s#>>'{actor,sessionId}' AND old.authenticated_at=(s#>>'{actor,authenticatedAt}')::timestamptz,'NG003');PERFORM pactwoven.native_google_session_fresh(s);RETURN old.review;END IF;
req:=jsonb_build_object('id',rid,'requestKey',key,'scope',ctx#>'{root,scope}','actorId',s#>>'{actor,actorId}','rootTaskId',q->>'rootTaskId','rootAuthority',ctx#>'{root,authority}','connectionId',q->>'connectionId','connectionVersion',c#>'{binding,connectionVersion}','accountSubject',c->>'accountSubject','membershipVersion',ctx#>'{authority,membershipVersion}','organizationEpoch',ctx#>'{authority,organizationEpoch}','target',q->'target','purpose',q->>'purpose','expiresAt',q->>'expiresAt','permission','read_correlated_inbound','outboundEffects','forbidden','continuesAfterSignOut',true);
PERFORM pactwoven.native_communication_validate(req,'request');bind:=jsonb_build_object('generation',ctx#>'{root,generation}','controlVersion',ctx#>'{root,controlVersion}','authority',ctx#>'{root,authority}');SELECT name INTO site_name FROM pactwoven.sites WHERE(environment,organization_id,id)=(env,s#>>'{actor,organizationId}',q->>'siteId');
review:=jsonb_build_object('id',rid,'token',pactwoven.native_delegation_hash(jsonb_build_object('namespace','pactwoven/google-calendar-review/v1','request',req,'binding',bind)),'rootTitle',ctx->>'rootTitle','siteName',site_name,'accountEmail',c->>'accountEmail','target',q->'target','purpose',q->>'purpose','preparedAt',pactwoven.mandate_instant(stamp),'confirmBy',pactwoven.mandate_instant(LEAST(stamp+interval '5 minutes',(q->>'expiresAt')::timestamptz)),'expiresAt',q->>'expiresAt','permission','read_single_calendar_event','outboundEffects','forbidden','continuesAfterSignOut',true);
PERFORM pactwoven.native_google_access_validate(review,'review');INSERT INTO pactwoven.native_google_access_reviews VALUES(env,s#>>'{actor,organizationId}',rid,s#>>'{actor,actorId}',key,SESSION_USER,(SELECT oid FROM pg_roles WHERE rolname=SESSION_USER),q,req,bind,review,s#>>'{actor,sessionId}',(s#>>'{actor,authenticatedAt}')::timestamptz,NULL,NULL);
PERFORM pactwoven.native_google_session_fresh(s);PERFORM pactwoven.native_google_require((q->>'expiresAt')::timestamptz>clock_timestamp() AND(ctx#>>'{authority,validUntil}')::timestamptz>clock_timestamp(),'NG008');RETURN review;END $$;
CREATE FUNCTION pactwoven.native_google_access_context(env text,r pactwoven.native_google_access_reviews,issued boolean,worker boolean)RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE c jsonb;ctx jsonb;h pactwoven.native_communication_heads;consent jsonb;BEGIN
c:=pactwoven.native_google_access_connection(env,r.request->>'connectionId');PERFORM pactwoven.native_google_access_producer(env,r.producer,r.producer_oid,'api');
IF issued THEN SELECT * INTO h FROM pactwoven.native_communication_heads WHERE(environment,organization_id,id)=(env,r.organization_id,r.id)FOR SHARE;SELECT body INTO consent FROM pactwoven.native_communication_consents WHERE(environment,organization_id,id)=(env,r.organization_id,r.id);PERFORM pactwoven.native_google_require(h.state='active' AND consent->'request'=r.request AND r.approval IS NOT NULL,'NG001');END IF;
ctx:=pactwoven.native_google_access_root(env,r.organization_id,r.actor_id,r.request->>'rootTaskId',r.request#>>'{scope,siteId}',worker);
PERFORM pactwoven.native_google_require(c#>>'{binding,actorId}'=r.actor_id AND c#>>'{binding,organizationId}'=r.organization_id AND c#>'{binding,connectionVersion}'=r.request->'connectionVersion' AND c->>'accountSubject'=r.request->>'accountSubject' AND r.binding=jsonb_build_object('generation',ctx#>'{root,generation}','controlVersion',ctx#>'{root,controlVersion}','authority',ctx#>'{root,authority}') AND ctx#>'{authority,membershipVersion}'=r.request->'membershipVersion' AND ctx#>'{authority,organizationEpoch}'=r.request->'organizationEpoch' AND(r.request->>'expiresAt')::timestamptz>clock_timestamp(),'NG001');RETURN ctx;END $$;
CREATE FUNCTION pactwoven.native_google_access_receipt(env text,s jsonb,rid text)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE r pactwoven.native_google_access_reviews;status text;BEGIN PERFORM pactwoven.native_google_access_lane(env,'api');PERFORM pactwoven.native_google_access_session(env,s);
SELECT * INTO r FROM pactwoven.native_google_access_reviews WHERE(environment,organization_id,id,actor_id)=(env,s#>>'{actor,organizationId}',rid,s#>>'{actor,actorId}');PERFORM pactwoven.native_google_require(FOUND,'NG001');PERFORM pactwoven.native_google_access_session(env,s,r.request#>>'{scope,siteId}');
SELECT state INTO status FROM pactwoven.native_communication_heads WHERE(environment,organization_id,id)=(env,r.organization_id,r.id);RETURN jsonb_build_object('id',r.id,'rootTitle',r.review->>'rootTitle','accountEmail',r.review->>'accountEmail','target',r.review->'target','expiresAt',r.review->'expiresAt','status',COALESCE(status,CASE WHEN r.approval IS NULL THEN 'prepared' ELSE 'approved' END));END $$;
CREATE FUNCTION pactwoven.native_google_access_confirm(env text,s jsonb,key text,q jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE r pactwoven.native_google_access_reviews;ctx jsonb;a jsonb;BEGIN PERFORM pactwoven.native_google_access_lane(env,'api');PERFORM pactwoven.native_google_access_validate(q,'confirm');PERFORM pactwoven.native_google_access_session(env,s);
SELECT * INTO r FROM pactwoven.native_google_access_reviews WHERE(environment,organization_id,id,actor_id,request_key)=(env,s#>>'{actor,organizationId}',q->>'reviewId',s#>>'{actor,actorId}',key);PERFORM pactwoven.native_google_require(FOUND,'NG001');ctx:=pactwoven.native_google_access_context(env,r,false,false);PERFORM pactwoven.native_google_access_session(env,s,r.request#>>'{scope,siteId}');
SELECT * INTO r FROM pactwoven.native_google_access_reviews WHERE(environment,organization_id,id)=(env,r.organization_id,r.id)FOR UPDATE;
PERFORM pactwoven.native_google_require(r.review->>'token'=q->>'reviewToken' AND r.session_id=s#>>'{actor,sessionId}' AND r.authenticated_at=(s#>>'{actor,authenticatedAt}')::timestamptz,'NG003');
IF r.approval IS NULL THEN
 PERFORM pactwoven.native_google_require((r.review->>'confirmBy')::timestamptz>clock_timestamp(),'NG003');a:=jsonb_build_object('actor',s->'actor','reviewDigest',pactwoven.native_delegation_hash(jsonb_build_object('namespace','pactwoven/channel-read-consent/v1','request',r.request)),'confirmedAt',s->>'verifiedAt','sessionVerifiedAt',s->>'verifiedAt','sessionExpiresAt',s->>'expiresAt');PERFORM pactwoven.native_communication_validate(a,'approval');UPDATE pactwoven.native_google_access_reviews SET approval=a,approval_session=s WHERE(environment,organization_id,id)=(env,r.organization_id,r.id);
END IF;
PERFORM pactwoven.native_google_session_fresh(s);PERFORM pactwoven.native_google_require((ctx#>>'{authority,validUntil}')::timestamptz>clock_timestamp() AND(r.request->>'expiresAt')::timestamptz>clock_timestamp(),'NG008');RETURN pactwoven.native_google_access_receipt(env,s,r.id);END $$;
-- A review is durable intent, not issued authority. First activation retains and
-- rechecks its original observer proof; active consent deliberately outlives sign-out.
CREATE FUNCTION pactwoven.native_google_access_issuance_session(env text,r pactwoven.native_google_access_reviews)RETURNS timestamptz LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE s jsonb:=r.approval_session;BEGIN
PERFORM pactwoven.native_google_require(s IS NOT NULL AND r.approval IS NOT NULL AND s->'actor'=r.approval->'actor' AND s->>'verifiedAt'=r.approval->>'sessionVerifiedAt' AND s->>'expiresAt'=r.approval->>'sessionExpiresAt' AND s#>>'{actor,sessionId}'=r.session_id AND(s#>>'{actor,authenticatedAt}')::timestamptz=r.authenticated_at,'NG001');
PERFORM pactwoven.native_google_access_session(env,s,r.request#>>'{scope,siteId}');
RETURN LEAST((s->>'expiresAt')::timestamptz,(s->>'verifiedAt')::timestamptz+interval '20 seconds');END $$;
CREATE FUNCTION pactwoven.native_google_access_review(env text,rid text)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE r pactwoven.native_google_access_reviews;ctx jsonb;BEGIN PERFORM pactwoven.native_google_access_lane(env,'review');SELECT * INTO r FROM pactwoven.native_google_access_reviews WHERE(environment,id)=(env,rid);PERFORM pactwoven.native_google_require(FOUND AND r.approval IS NOT NULL,'NG001');ctx:=pactwoven.native_google_access_context(env,r,false,false);PERFORM pactwoven.native_google_access_issuance_session(env,r);PERFORM pactwoven.native_google_require((r.approval->>'sessionVerifiedAt')::timestamptz>clock_timestamp()-interval '20 seconds' AND(r.approval->>'sessionExpiresAt')::timestamptz>clock_timestamp(),'NG008');RETURN jsonb_build_object('request',r.request,'approval',r.approval);END $$;
CREATE OR REPLACE FUNCTION pactwoven.native_google_bridge_read(env text,input jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
#variable_conflict use_variable
DECLARE r pactwoven.native_google_access_reviews;ctx jsonb;stamp timestamptz;answer jsonb;BEGIN SELECT * INTO r FROM pactwoven.native_google_access_reviews WHERE(environment,id)=(env,input->>'providerReference')FOR SHARE;PERFORM pactwoven.native_google_require(FOUND AND r.request->>'connectionId'=input->>'connectionId','NG001');ctx:=pactwoven.native_google_access_context(env,r,true,true);stamp:=clock_timestamp();answer:=jsonb_build_object('providerReference',r.id,'request',r.request,'observedAt',pactwoven.mandate_instant(stamp),'validUntil',ctx#>'{authority,validUntil}');PERFORM pactwoven.native_google_read_fresh(answer);RETURN answer;END $$;
CREATE FUNCTION pactwoven.native_google_access_immutable()RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN RAISE EXCEPTION USING ERRCODE='NG003',MESSAGE='Immutable private Calendar content';END $$;
CREATE TRIGGER native_google_access_content_immutable BEFORE UPDATE OR DELETE ON pactwoven.native_google_access_contents FOR EACH ROW EXECUTE FUNCTION pactwoven.native_google_access_immutable();
CREATE FUNCTION pactwoven.native_google_access_content(env text,r jsonb,event jsonb,digest text)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE ctx jsonb;ref jsonb;rid text;prior pactwoven.native_google_access_contents;target jsonb;BEGIN PERFORM pactwoven.native_google_access_lane(env,'content');PERFORM pactwoven.native_google_validate(r,'read');PERFORM pactwoven.native_google_access_validate(event,'event');ctx:=pactwoven.native_google_read(env,r#>>'{request,connectionId}',r->>'providerReference');PERFORM pactwoven.native_google_require(ctx#>'{read,request}'=r->'request' AND event->>'status'<>'cancelled' AND event->>'id'=r#>>'{request,target,eventId}' AND(event->>'updated')::timestamptz<=clock_timestamp() AND digest=pactwoven.native_delegation_hash(jsonb_build_object('namespace','pactwoven/google-calendar-event/v1','event',event)),'NG001');
target:=jsonb_build_object('calendarId',r#>>'{request,target,calendarId}','eventId',event->>'id','etag',event->>'etag');rid:=pactwoven.native_delegation_hash(jsonb_build_object('namespace','pactwoven/google-content/v1','scope',r#>'{request,scope}','connectionId',r#>>'{request,connectionId}','target',target,'eventDigest',digest));ref:=jsonb_build_object('scope',r#>'{request,scope}','id',rid,'revision',1,'digest',digest);
INSERT INTO pactwoven.native_google_access_contents VALUES(env,rid,r#>>'{request,connectionId}',target,digest,ref,event)ON CONFLICT DO NOTHING;SELECT * INTO prior FROM pactwoven.native_google_access_contents WHERE(environment,id)=(env,rid);PERFORM pactwoven.native_google_require(prior.body=event AND prior.reference=ref AND prior.event_digest=digest,'NG003');PERFORM pactwoven.native_google_read_fresh(ctx->'read');RETURN ref;END $$;
CREATE OR REPLACE FUNCTION pactwoven.native_google_bridge_artifact(env text,input jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE a pactwoven.native_google_access_contents;p jsonb:=input->'provenance';r jsonb:=input->'read';BEGIN SELECT * INTO a FROM pactwoven.native_google_access_contents WHERE(environment,id)=(env,p#>>'{message,content,id}')FOR SHARE;
PERFORM pactwoven.native_google_require(FOUND AND a.reference=p#>'{message,content}' AND a.event_digest=p->>'eventDigest' AND a.connection_id=r#>>'{request,connectionId}' AND a.reference->'scope'=r#>'{request,scope}' AND a.target->>'calendarId'=r#>>'{request,target,calendarId}' AND a.target->>'eventId'=r#>>'{request,target,eventId}' AND a.target->>'etag'=p#>>'{message,source,etag}' AND a.body->>'updated'=p#>>'{message,occurredAt}','NG001');RETURN a.reference;END $$;

CREATE FUNCTION pactwoven.native_google_access_revoke_consent(env text,s jsonb,rid text,expected bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE r pactwoven.native_google_access_reviews;h pactwoven.native_communication_heads;BEGIN
PERFORM pactwoven.native_google_access_lane(env,'api');PERFORM pactwoven.native_google_access_session(env,s);
SELECT * INTO r FROM pactwoven.native_google_access_reviews WHERE(environment,organization_id,id,actor_id)=(env,s#>>'{actor,organizationId}',rid,s#>>'{actor,actorId}');PERFORM pactwoven.native_google_require(FOUND,'NG001');PERFORM pactwoven.native_google_access_session(env,s,r.request#>>'{scope,siteId}');
SELECT * INTO h FROM pactwoven.native_communication_heads WHERE(environment,organization_id,id)=(env,r.organization_id,rid)FOR UPDATE;PERFORM pactwoven.native_google_require(FOUND AND h.state='active' AND h.version=expected,'NG003');
UPDATE pactwoven.native_communication_heads SET state='revoked',version=version+1 WHERE(environment,organization_id,id)=(env,r.organization_id,rid);PERFORM pactwoven.native_google_session_fresh(s);RETURN pactwoven.native_google_access_receipt(env,s,rid);END $$;

-- Source: .local/native-google-access/communication-bridges.sql
-- Proposed production bridge bodies. Does not implement enter_wait or wake.
CREATE OR REPLACE FUNCTION pactwoven.native_communication_bridge_connection(req jsonb,actor jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE r pactwoven.native_google_access_reviews;c jsonb;stamp timestamptz;env text:=req#>>'{scope,environment}';BEGIN
SELECT * INTO r FROM pactwoven.native_google_access_reviews WHERE(environment,organization_id,id)=(env,req#>>'{scope,organizationId}',req->>'id');PERFORM pactwoven.native_google_require(FOUND AND r.request=req AND r.approval IS NOT NULL,'NG001');
c:=pactwoven.native_google_access_connection(env,req->>'connectionId');stamp:=clock_timestamp();RETURN jsonb_build_object('id',req->>'connectionId','version',c#>'{binding,connectionVersion}','environment',env,'organizationId',c#>>'{binding,organizationId}','actorId',c#>>'{binding,actorId}','provider','google','accountSubject',c->>'accountSubject','status',CASE WHEN c->>'status'='connected' THEN 'connected' ELSE 'unavailable' END,'oauthScopes',jsonb_build_array('https://www.googleapis.com/auth/calendar.events.readonly'),'observedAt',pactwoven.mandate_instant(stamp),'validUntil',pactwoven.mandate_instant(stamp+interval '15 seconds'));END $$;
CREATE OR REPLACE FUNCTION pactwoven.native_communication_bridge_authority(req jsonb,actor jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE r pactwoven.native_google_access_reviews;ctx jsonb;session_until timestamptz;issued boolean;env text:=req#>>'{scope,environment}';BEGIN
SELECT * INTO r FROM pactwoven.native_google_access_reviews WHERE(environment,organization_id,id)=(env,req#>>'{scope,organizationId}',req->>'id')FOR SHARE;PERFORM pactwoven.native_google_require(FOUND AND r.request=req AND r.approval IS NOT NULL,'NG001');
IF actor<>'null'::jsonb THEN PERFORM pactwoven.native_google_require(actor->>'principalKind'='human' AND actor->>'actorId'=r.actor_id AND actor->>'organizationId'=r.organization_id AND actor->>'environment'=env AND actor->>'sessionId'=r.session_id AND(actor->>'authenticatedAt')::timestamptz=r.authenticated_at,'NG001');END IF;
ctx:=pactwoven.native_google_access_context(env,r,actor='null'::jsonb,actor='null'::jsonb);
IF actor<>'null'::jsonb THEN
 SELECT EXISTS(SELECT 1 FROM pactwoven.native_communication_consents WHERE(environment,organization_id,id)=(env,r.organization_id,r.id))INTO issued;
 IF NOT issued THEN session_until:=pactwoven.native_google_access_issuance_session(env,r);ctx:=jsonb_set(ctx,'{authority,validUntil}',to_jsonb(pactwoven.mandate_instant(LEAST(session_until,(ctx#>>'{authority,validUntil}')::timestamptz))));END IF;
END IF;RETURN jsonb_build_object('authority',ctx->'authority','root',ctx->'root');END $$;
CREATE OR REPLACE FUNCTION pactwoven.native_communication_bridge_artifact(req jsonb,reference jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE a pactwoven.native_google_access_contents;BEGIN SELECT * INTO a FROM pactwoven.native_google_access_contents WHERE(environment,id)=(req#>>'{scope,environment}',reference->>'id')FOR SHARE;
PERFORM pactwoven.native_google_require(FOUND AND a.reference=reference AND a.reference->'scope'=req->'scope' AND a.connection_id=req->>'connectionId' AND a.target->>'calendarId'=req#>>'{target,calendarId}' AND a.target->>'eventId'=req#>>'{target,eventId}','NG001');RETURN a.reference;END $$;
DO $$ DECLARE t record;f record;BEGIN
 FOR t IN SELECT c.oid::regclass relation,c.relname FROM pg_class c WHERE c.relnamespace='pactwoven'::regnamespace AND c.relkind='r' AND (c.relname LIKE 'native_google_access_%' OR c.relname LIKE 'native_google_bridge_%' OR c.relname LIKE 'native_communication_bridge_%') LOOP
  EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY',t.relation);EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY',t.relation);
  EXECUTE format('REVOKE ALL ON TABLE %s FROM PUBLIC',t.relation);
  IF NOT EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=t.relation AND polname='google_production_owner') THEN EXECUTE format('CREATE POLICY google_production_owner ON %s TO %I USING(true) WITH CHECK(true)',t.relation,CURRENT_USER);END IF;
 END LOOP;
 FOR f IN SELECT oid::regprocedure signature FROM pg_proc WHERE pronamespace='pactwoven'::regnamespace AND (proname LIKE 'native_google_access_%' OR proname LIKE 'native_google_bridge_%' OR proname LIKE 'native_communication_bridge_%') LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);END LOOP;
END $$;
COMMIT;
